SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2022.Year, Станции2022.NUST, Станции2022.nr, Станции2022.E, Станции2022.EOTP, Станции2022.EURT, Станции2022.EUST, Станции2022.Q, Станции2022.TURT, Станции2022.TUST, Станции2022.B, Станции2022.GAZ, Доп_угли2022.gaz_prir, Доп_угли2022.gazpp, Станции2022.MAZUT, Доп_угли2022.maztop, Доп_угли2022.gtt, Доп_угли2022.nft_proch, Доп_угли2022.disel, Станции2022.TORF, Станции2022.SLAN, Станции2022.ISK_GAZ, Доп_угли2022.domen_g, Доп_угли2022.koks_g, Доп_угли2022.prochgaz, Станции2022.PROCH, Доп_угли2022.tvproch, Доп_угли2022.szh_gaz, Доп_угли2022.inoe, Станции2022.UGOL, Станции2022.DON, Станции2022.PODM, Станции2022.PECH, Доп_угли2022.intin, Доп_угли2022.vork, Станции2022.ARKT, Станции2022.KUZN, Доп_угли2022.kuzngd, Доп_угли2022.kuznt, Доп_угли2022.kuznss, Доп_угли2022.kuznun, Станции2022.URAL, Доп_угли2022.sver, Доп_угли2022.chel, Доп_угли2022.kizel, Станции2022.BASHK, Станции2022.KAN, Доп_угли2022.nazar, Доп_угли2022.ibor, Доп_угли2022.berez, Доп_угли2022.per, Доп_угли2022.irbei, Доп_угли2022.kansk, Станции2022.TUNG, Доп_угли2022.jer, Доп_угли2022.karab, Станции2022.IRKUT, Доп_угли2022.azey, Доп_угли2022.mug, Доп_угли2022.cher, Станции2022.HAK, Станции2022.TUV, Станции2022.BUR, Доп_угли2022.gusin, Доп_угли2022.tugn, Доп_угли2022.okino, Станции2022.CHIT, Доп_угли2022.har, Доп_угли2022.urt, Доп_угли2022.tataur, Доп_угли2022.tarbag, Доп_угли2022.zab_kam, Станции2022.YAKUT, Доп_угли2022.neru, Доп_угли2022.zyryan, Доп_угли2022.pyak, Станции2022.AMUR, Доп_угли2022.rai, Доп_угли2022.erk, Доп_угли2022.ogodj, Станции2022.URG, Станции2022.USHUM, Станции2022.PRIM, Доп_угли2022.bikin, Доп_угли2022.razdol, Доп_угли2022.hankai, Станции2022.MAG, Станции2022.SAH, Станции2022.KAMCH, Станции2022.CHUKOT, Доп_угли2022.anad, Доп_угли2022.bering, Станции2022.KAZAH, Доп_угли2022.ekib, Доп_угли2022.maikub, Доп_угли2022.karag, Доп_угли2022.karajyra, Доп_угли2022.teniz, Станции2022.QOTR, Станции2022.SNK, Станции2022.EWTP, Станции2022.NT, Станции2022.OBOR, Станции2022.VED, Станции2022.OBL, Станции2022.DEP, Станции2022.OES, Станции2022.ER, Станции2022.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"ГУБТ",IIf([obor]=24 Or [obor]=89,"ГПА","ПСУ"))))) AS тип, Станции2022.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz]/[B]*100,0) AS dolya_gaz, IIf([B]>0,[ugol]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[mazut]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[torf]/[B]*100,0) AS dolya_torf, IIf([B]>0,[slan]/[B]*100,0) AS dolya_slan, IIf([B]>0,[proch]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf(([dolya_gaz]+[dolya_domen_g]+[dolya_koks_g]+[dolya_prochgaz])>=50,"gaz",IIf([dolya_ugol]>=50,"ugol","prochee")) AS Belyaev, [EUST]/[B] AS [dolya topl na ee], [TUST]/[B] AS [dolya topl na q], Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций].[BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Имена_станций].[Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([Станции2022].[вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved
FROM ((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции2022 LEFT JOIN Доп_угли2022 ON (Станции2022.NUMB1120 = Доп_угли2022.NUMB1120) AND (Станции2022.YEAR = Доп_угли2022.YEAR)) ON Имена_ОЭС.oes = Станции2022.OES) ON Имена_областей.OBL = Станции2022.OBL) ON Имена_станций.NUMB = Станции2022.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code;
